PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS app_memberships (subject TEXT PRIMARY KEY,display_name TEXT,role TEXT NOT NULL DEFAULT 'viewer' CHECK(role IN ('admin','supervisor','process_owner','operator','viewer','auditor')),active INTEGER NOT NULL DEFAULT 0 CHECK(active IN(0,1)),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',department TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','disabled')),model TEXT NOT NULL DEFAULT '@cf/meta/llama-3.3-70b-instruct-fp8-fast',provider TEXT NOT NULL DEFAULT 'workers-ai',monthly_limit INTEGER NOT NULL DEFAULT 100,instruction_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_instructions (id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES agents(id),version INTEGER NOT NULL,instructions TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(agent_id,version));
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,order_number TEXT,client TEXT,issued_at TEXT,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN ('received','processing','review','blocked','approved','csv_generated','completed','error')),version INTEGER NOT NULL DEFAULT 1,origin TEXT NOT NULL DEFAULT 'manual',email_message_id TEXT UNIQUE,created_by TEXT NOT NULL,assigned_to TEXT,notes TEXT,last_error TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_orders_status ON orders(status,updated_at DESC);
CREATE INDEX IF NOT EXISTS ix_orders_client ON orders(client);
CREATE TABLE IF NOT EXISTS order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,sku TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',quantity REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL DEFAULT '',unit_price REAL,currency TEXT NOT NULL DEFAULT '',technical_status TEXT NOT NULL DEFAULT 'unknown' CHECK(technical_status IN ('approved','pending','rejected','missing','unknown')),technical_checked_at TEXT,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_order_lines_order ON order_lines(order_id,sort_order);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,original_filename TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,r2_key TEXT NOT NULL UNIQUE,extraction_status TEXT NOT NULL DEFAULT 'queued' CHECK(extraction_status IN ('queued','processing','review','error')),extracted_text TEXT,extraction_json TEXT,failure_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,sha256));
CREATE TABLE IF NOT EXISTS erp_csv_mappings(id TEXT PRIMARY KEY,name TEXT NOT NULL,version INTEGER NOT NULL,config TEXT NOT NULL,validated INTEGER NOT NULL DEFAULT 0 CHECK(validated IN(0,1)),validated_by TEXT,validated_at TEXT,active INTEGER NOT NULL DEFAULT 0 CHECK(active IN(0,1)),UNIQUE(name,version));
CREATE UNIQUE INDEX IF NOT EXISTS ux_erp_mapping_active ON erp_csv_mappings(active) WHERE active=1;
CREATE TABLE IF NOT EXISTS generated_csvs(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),mapping_id TEXT NOT NULL REFERENCES erp_csv_mappings(id),r2_key TEXT NOT NULL UNIQUE,hash TEXT NOT NULL,generated_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,loaded_by TEXT,loaded_at TEXT);
CREATE TABLE IF NOT EXISTS integration_cursors(name TEXT PRIMARY KEY,cursor_url TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_reference(kind TEXT NOT NULL,code TEXT NOT NULL,label TEXT NOT NULL,source_version TEXT NOT NULL,imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(kind,code,source_version));
CREATE TABLE IF NOT EXISTS executions(id TEXT PRIMARY KEY,agent_slug TEXT NOT NULL,order_id TEXT REFERENCES orders(id),document_id TEXT REFERENCES documents(id),status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,model TEXT,duration_ms INTEGER,estimated_cost_usd REAL,error TEXT,started_at TEXT,finished_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_subject TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_audit_events_time ON audit_events(occurred_at DESC);
CREATE TRIGGER IF NOT EXISTS tr_audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'AUDIT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS tr_audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'AUDIT_IMMUTABLE'); END;
CREATE TABLE IF NOT EXISTS permission_catalog(code TEXT PRIMARY KEY,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role TEXT NOT NULL,permission_code TEXT NOT NULL REFERENCES permission_catalog(code),PRIMARY KEY(role,permission_code));
CREATE TABLE IF NOT EXISTS agent_tools(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,tool_contract TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_tool_grants(agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE,tool_id TEXT NOT NULL REFERENCES agent_tools(id) ON DELETE CASCADE,granted_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(agent_id,tool_id));
CREATE TABLE IF NOT EXISTS knowledge_sources(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,source_type TEXT NOT NULL,access_policy TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS automations(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,schedule_cron TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','enabled','disabled')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS received_emails(id TEXT PRIMARY KEY,graph_message_id TEXT NOT NULL UNIQUE,order_id TEXT REFERENCES orders(id),sender_address TEXT,subject TEXT,received_at TEXT,status TEXT NOT NULL DEFAULT 'received',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_approvals(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),actor_subject TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')),reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_extractions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),model TEXT,extraction TEXT NOT NULL,reviewed_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integration_registry(name TEXT PRIMARY KEY,integration_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',metadata TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
